phase = 'recover'
timer = 0.0
def control(obs):
    global phase, timer
    timer += obs.get('dt', 0.1)
    h = obs.get('hitch_deg', 0.0)
    status = obs.get('status', '')
    if phase == 'recover':
        # Pull forward briefly so the trailer clears the contacted rail.
        if timer < 3.0:
            return (0.0, 0.65, -23)
        phase = 'reverse'
        timer = 0.0
    # Ease back into the course, biasing the trailer away from the right rail.
    steer = max(-12.0, min(18.0, 1.1 * h + 8.0))
    speed = -0.30 if timer < 4.0 else -0.42
    if abs(h) > 20:
        speed = -0.22
    return (steer, speed, -23)

