    covered=obs.get('progress',{}).get('covered',0.0)
    status=obs.get('status')
    if start is None: start=covered
    if status=='PINNED' or status=='PULLING_FORWARD' and start-covered<2.0:
        return (0.0,0.6,170)
    # After backing clear, use rearward rail distances to bias away from the nearer side.
    view=obs.get('views',{}).get('direct',{})
    rails=view.get('walls',[])
    left=[]; right=[]
    for b,d in rails:
        if d>0 and 90<abs(b)<180:
            y=d*__import__('math').sin(__import__('math').radians(b))
            if y>0: left.append(d)
            else: right.append(d)
    h=obs.get('hitch_deg',0.0)
    bias=0.0
    if left and right:
        # Positive steer moves the trailer rear toward its right during reverse.
        bias=max(-5.0,min(5.0,2.0*(1.0/min(left)-1.0/min(right))))
    steer=max(-7.0,min(7.0,0.45*h+bias))
    return (steer,-0.22,170)

