phase='clear'
def control(obs):
    global phase
    h=obs.get('hitch_deg',0.0)
    if phase=='clear':
        if obs.get('status') not in ('PINNED','JACKKNIFED') and obs.get('progress',{}).get('covered',0)>5.2:
            phase='reverse'
        else:
            return (0,0.40,0)
    steer=max(-18,min(18,1.1*h))
    return (steer,-0.22 if abs(h)<12 else -0.15,170)

