def control(obs):
    h = obs.get('hitch_deg', 0.0)
    status = obs.get('status', '')
    # Forward recovery clears the pinned corner and lets the long trailer settle.
    if status == 'PINNED' or (status == 'PULLING_FORWARD' and abs(h) > 2.0):
        return (max(-10.0, min(10.0, -0.5*h)), 0.35, -41.0)
    views = obs.get('views', {})
    cam = views.get('camera') or {}
    walls = cam.get('walls', [])
    right = 99.0
    left = 99.0
    import math
    for b, d in walls:
        side = math.sin(math.radians(b))
        if side < -0.22:
            right = min(right, d)
        elif side > 0.22:
            left = min(left, d)
    bias = 0.0
    if right < 3.5:
        bias = -min(14.0, 3.0 + 2.0*(3.5-right))
    elif left < 3.5:
        bias = min(14.0, 3.0 + 2.0*(3.5-left))
    steer = max(-18.0, min(18.0, 0.65*h + bias))
    return (steer, -0.35, -41.0)

